bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || { echo VIDEO_POLL_NOT_RUNNING; exit 45; }
printf 'LIVE_GSERVER_SHA='
git -C /home/gace/Project/Gserver/repository rev-parse HEAD
printf 'LIVE_VIDEO_IMAGE='
docker inspect "$cid" --format '{{.Config.Image}}'
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const pool=new pg.Pool({
 host:process.env.VIDEOBOT_DB_HOST,
 user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,
 password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:4500
});
try {
 const c=await pool.query("SELECT to_regclass('public.videobot_rich_offer_receipts') IS NOT NULL AS rich_receipts_available");
 const r=await pool.query("SELECT l.listing_id,l.revision,l.status AS listing_status,r.status AS receipt_status,r.sale_mode,r.paid_message_id,r.free_message_ids,r.topic_id FROM videobot_listings l JOIN videobot_post_receipts r ON r.listing_id=l.listing_id AND r.delivery_key=l.listing_id||':'||l.revision::text WHERE l.listing_id=$1",['v26nov24invoice']);
 const p=await pool.query("SELECT COUNT(*)::int AS n FROM videobot_video_invoice_orders WHERE delivery_key=$1",['v26nov24invoice:1']);
 const h=await pool.query("SELECT COUNT(*)::int AS n FROM videobot_stars_ledger p JOIN videobot_listings o ON o.listing_id=p.listing_id JOIN videobot_listings l ON l.seller_user_id=o.seller_user_id AND l.paid_video_file_id=o.paid_video_file_id WHERE p.kind='paid' AND l.listing_id=$1",['v26nov24invoice']);
 const x=r.rows?.[0]||null;
 console.log('LIVE_RECEIPT=' + JSON.stringify({listingId:x?.listing_id,revision:x?.revision,listingStatus:x?.listing_status,receiptStatus:x?.receipt_status,saleMode:x?.sale_mode,paidMessageId:Number(x?.paid_message_id||0),freePreviewCount:x?.free_message_ids?.length||0,topicId:Number(x?.topic_id||0),richReceiptsAvailable:c.rows[0].rich_receipts_available,priorOrders:p.rows[0].n,historicBuyers:h.rows[0].n}));
}finally{await pool.end();}
JS
